package com.sellerdesk.product.model;

import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;
import org.springframework.data.mongodb.core.mapping.Field;
import org.springframework.data.mongodb.core.mapping.FieldType;

/** A product photo stored in Cloudinary. Embedded in the product; the first one is the cover. */
@Getter
@Setter
@NoArgsConstructor
@ToString
public class ProductImage {

    /** Generated by the app. */
    @Field(targetType = FieldType.OBJECT_ID)
    private String imageId;

    /** Cloudinary {@code secure_url}. */
    private String url;

    /** Cloudinary id, needed to delete the file. Never returned to clients. */
    private String publicId;

    private int width;

    private int height;

    private long bytes;

    private String format;
}
